func _streqci(tls *libc.TLS, s1 uintptr, s2 uintptr) (r int32) {
	var c1, c2 int8
	var v2, v3 uintptr
	_, _, _, _ = c1, c2, v2, v3
	for {
		v2 = s1
		s1 = s1 + 1
		c1 = **(**int8)(__ccgo_up(v2))
		v3 = s2
		s2 = s2 + 1
		c2 = **(**int8)(__ccgo_up(v3))
		if int32(MASCII_a) <= int32(c1) && int32(c1) <= int32(MASCII_z) {
			c1 = int8(int32(c1) + (libc.Int32FromInt32(MASCII_A) - libc.Int32FromInt32(MASCII_a)))
		}
		if int32(MASCII_a) <= int32(c2) && int32(c2) <= int32(MASCII_z) {

			c2 = int8(int32(c2) + (libc.Int32FromInt32(MASCII_A) - libc.Int32FromInt32(MASCII_a)))
		}
		if int32(c1) != int32(c2) {
			return 0
		}
		if !(c1 != 0) {
			break
		}
		goto _1
	_1:
	}
	return int32(1)
}

